/// <summary>
/// designed from AVA
/// </summary>
public void init()
{
    next init();

    FormStringControl avaInventColorId_Grid = this.design().controlName(formControlStr(SalesTable, InventoryDimensionsGrid_InventColorId));
    avaInventColorId_Grid.registerOverrideMethod(methodStr(FormDataObject, lookup), methodStr(AVASalesTableFrm_Extension, avaColorLookup));
    FormStringControl avaInventColorId_Details = this.design().controlName(formControlStr(SalesTable, InventoryDimensions_InventColorId));
    avaInventColorId_Details.registerOverrideMethod(methodStr(FormDataObject, lookup), methodStr(AVASalesTableFrm_Extension, avaColorLookup));

    FormReferenceGroupControl fcSalesLine_SalesCategory = this.design().controlName(formControlStr(SalesTable, SalesLine_SalesCategory));
    fcSalesLine_SalesCategory.visible(false);

    FormRealControl fcSalesLine_PdsCWInventDeliverNow = this.design().controlName(formControlStr(SalesTable, SalesLine_PdsCWInventDeliverNow));
    fcSalesLine_PdsCWInventDeliverNow.visible(false);

    this.design().controlName(formControlStr(SalesTable, AVASCMCheckIfMarkup_SalesLine)).skip(NoYes::Yes);
    this.design().controlName(formControlStr(SalesTable, SalesLine_SalesUnit)).skip(NoYes::Yes);
    this.design().controlName(formControlStr(SalesTable, SalesLine_ShippingDateRequested)).allowEdit(NoYes::No);

    SalesLine_ds.object(fieldNum(SalesLine, ItemId)).registerOverrideMethod(methodStr(FormDataObject, lookup), formMethodStr(SalesTable, avaOverrideItemIdLookup), this);
    //SalesLine_ds.object(fieldNum(SalesLine, PdsCWInventDeliverNow)).visible(false);
    //SalesLine_ds.object(fieldNum(SalesLine, SalesCategory)).visible(false);
    SalesLine_ds.object(fieldNum(SalesLine, ShippingDateRequested)).allowEdit(NoYes::No);

    if (!xUserInfo::checkUserOrAdminRole('AVAOrderReplenishment'))       // maybe roleStr(AVAOrderReplenishment) better?
    {
        SalesLine_ds.object(fieldNum(SalesLine, ShippingDateConfirmed)).allowEdit(NoYes::No);
        SalesLine_ds.object(fieldNum(SalesLine, ReceiptDateConfirmed)).allowEdit(NoYes::No);
        SalesTable_ds.object(fieldNum(SalesTable, ShippingDateConfirmed)).allowEdit(NoYes::No);
        SalesTable_ds.object(fieldNum(SalesTable, ReceiptDateConfirmed)).allowEdit(NoYes::No);
        this.design().controlName(formControlStr(SalesTable, SalesLine_ShippingDateConfirmed)).allowEdit(NoYes::No);
        this.design().controlName(formControlStr(SalesTable, SalesLine_ReceiptDateConfirmed)).allowEdit(NoYes::No);
        this.design().controlName(formControlStr(SalesTable, Delivery_ShippingDateConfirmed)).allowEdit(NoYes::No);
        this.design().controlName(formControlStr(SalesTable, Delivery_ReceiptDateConfirmed)).allowEdit(NoYes::No);
        this.design().controlName(formControlStr(SalesTable, Delivery_ShippingDateConfirmedHeader)).allowEdit(NoYes::No);
        this.design().controlName(formControlStr(SalesTable, Delivery_ReceiptDateConfirmedHeader)).allowEdit(NoYes::No);
    }

    if (!xUserInfo::checkUserOrAdminRole('AVAICReductionMaintain'))
    {
        SalesTable_ds.object(fieldNum(SalesTable, KCS_IC_Reduction)).allowEdit(NoYes::No);
    }


    this.avaShowHideItemSetComponents(false, true);
    this.avaInterCompanyFields();

    this.avaSetBottonsAfterInit();
}

public void avaSalesLineTexteEditable()
{
    if(salesLine.AVAOverwriteText
        || salesTable.NDX_ItemNameVersionReport == NDX_ItemNameVersionReport::LongText)
    {
        salesLine_DS.object(fieldNum(SalesLine, Name)).allowEdit(true);
    }
    else
    {
        salesLine_DS.object(fieldNum(SalesLine, Name)).allowEdit(false);
    }
}

