/// <summary>
/// desigend from AVA
/// </summary>
/// <param name = "_callerObject">_callerObject</param>
public void avaQuotationJumpRef(FormDataObject _callerObject)
{
    SalesQuotationTable avaQuotationTable;
    Args            args = new Args();
    MenuFunction    menuFunction;
    ;

    if (_callerObject.getValue() != '')
    {
        menuFunction = new MenuFunction(menuitemDisplayStr(SalesQuotationTable), MenuItemType::Display);
        avaQuotationTable = SalesQuotationTable::find(_callerObject.getValue());
        if (avaQuotationTable.RecId != 0)
        {
            args.record(avaQuotationTable);
            args.caller(this);
            menuFunction.run(args);
        }
    }

}

/// <summary>
/// designed from AVA
/// </summary>
/// <param name = "_formStringControl">_formStringControl</param>
public void avaColorLookup(FormStringControl _formStringControl)
{
    Args locArgs = new Args(identifierStr(AVAEcoResColorLookup));
    FormRun avaLookupFormRun;

    locArgs.record(SalesLine);
    locArgs.caller(this);

    avaLookupFormRun = classFactory::formRunClassOnClient(locArgs);
    avaLookupFormRun.init();

    _formStringControl.performFormLookup(avaLookupFormRun);
    avaLookupFormRun.wait();

}

/// <summary>
///    AVA <c>avaRefreshSalesLineDS</c> method.
/// </summary>
public void avaRefreshSalesLineDS()
{
    FormDataSource  locSalesLineDS;

    locSalesLineDS = SalesLine_DS;

    locSalesLineDS.research(true);
    locSalesLineDS.refresh();
}

/// <summary>
/// method to override the lookup method of SalesQuotationLine dataSource field ItemId
/// </summary>
/// <param name = "_formControl">FormStringControl</param>
public void avaOverrideItemIdLookup(FormStringControl _formControl)
{
    FormDataObject avaSalesLine_ItemId = SalesLine_ds.object(fieldNum(SalesLine, ItemId));

    if ((!mcrCallCenterEnabled || salesLine.mcrSalesLine().SourceId == '')
        && EcoResProductParameters::find().pcLookupMethod != PCLookupMethod::Configurable
        && !EcoResProductSearchLookup::isProductSearchLookupEnabled())
    {
        this.avaItemIdLookup(_formControl);
    }
    else
    {
        avaSalesLine_ItemId.lookup(_formControl, _formControl.text());
    }
}

/// <summary>
/// Creates lookup using the form InventItemIdLookupSimpleView
/// </summary>
/// <param name = "_formControl">FormStringControl</param>
public void avaItemIdLookup(FormStringControl _formControl)
{
    Query                   avaQuery = new Query();
    InventLookupItemId      inventLookupItemId;

    QueryBuildDataSource    itemIdLookup_qbds   = avaQuery.addDataSource(tableNum(InventItemIdLookupSimpleView));

    itemIdLookup_qbds.addSortField(fieldNum(InventItemIdLookupSimpleView, ItemId));
    itemIdLookup_qbds.firstFast(true);

    if(MCRFullTextParameters::isProductSearchLookupSalesItemEnabled())
    {
        itemIdLookup_qbds.addRange(fieldNum(InventItemIdLookupSimpleView, KCS_IsSalesItem)).value(queryValue(NoYes::Yes));
    }

    inventLookupItemId = InventLookupItemId::newLookupCtrlQuery(_formControl, avaQuery);
    inventLookupItemId.run();
}

/// <summary>
///    AVA <c>avaShowHideItemSetComponents</c> method.
/// </summary>
/// <param name="_research">
///    <c>boolean</c> as type
/// </param>
/// <param name="_init">
///    <c>boolean</c> as type
/// </param>
/// <returns>
///    <c>boolean</c> as return value
/// </returns>
public boolean avaShowHideItemSetComponents(boolean _research = false, boolean _init = false)
{
    boolean         retVal;

    FormDataSource  avaSalesLineDS;

    avaSalesLineDS  = this.SalesLine_DS;
    retVal          = true;

    if(_init)
    {
        frmAVAItemSetShowComponents = false;
    }
    else
    {
        frmAVAItemSetShowComponents = !frmAVAItemSetShowComponents;
    }

    if (frmAVAItemSetShowComponents)
    {
        SysQuery::findOrCreateRange(avaSalesLineDS.queryBuildDataSource(), fieldNum(SalesLine, AVAItemSetComponent)).value(SysQueryRangeUtil::valueUnlimited());
    }
    else
    {
        SysQuery::findOrCreateRange(avaSalesLineDS.queryBuildDataSource(), fieldNum(SalesLine, AVAItemSetComponent)).value(SysQuery::value(NoYes::No));
    }

    if(_research)
    {
        avaSalesLineDS.research(true);
    }

    return retVal;
}

/// <summary>
///    AVA <c>avaInterCompanyFields</c> method.
/// </summary>
/// <returns>
///    <c>boolean</c> as return value
/// </returns>
public boolean avaInterCompanyFields()
{
    boolean         retVal;

    FormDataSource  locSalesTableDS;
    SalesTable      locSalesTable;
    boolean         isIC, isICDirectDlv;        
    retVal = true;

    locSalesTableDS = this.SalesTable_DS;
    locSalesTable   = locSalesTableDS.cursor();

    isic = locSalesTable.isInterCompanyOrder();
    isICDirectDlv = locSalesTable.InterCompanyDirectDelivery;

    /*if(locSalesTable.isInterCompanyOrder())
    {
        this.design().controlName(formControlStr(SalesTable, AVAShippingCharges_KCS_FreightCostStatus)).allowEdit(NoYes::No);
        this.design().controlName(formControlStr(SalesTable, AVAShippingCharges_KCS_POC_CarriageFree)).allowEdit(NoYes::No);
        this.design().controlName(formControlStr(SalesTable, AVAShippingCharges_KCS_FreightCalculation)).allowEdit(NoYes::No);
        this.design().controlName(formControlStr(SalesTable, AVAShippingCharges_KCS_FreightChargeFree)).allowEdit(NoYes::No);
    }*/
    locSalesTableDS.object(fieldNum(SalesTable, KCS_FreightCostStatus)).allowEdit(!isIC);
    locSalesTableDS.object(fieldNum(SalesTable, KCS_POC_CarriageFree)).allowEdit(!isic);
    locSalesTableDS.object(fieldNum(SalesTable, KCS_FreightCalculation)).allowEdit(!isIC);
    locSalesTableDS.object(fieldNum(SalesTable, KCS_FreightChargeFree)).allowEdit(!isIC);

    locSalesTableDS.object(fieldNum(SalesTable, AVADlvResponsible)).allowEdit(!isICDirectDlv);
    locSalesTableDS.object(fieldNum(SalesTable, InventSiteId)).allowEdit(!isICDirectDlv);


    return retVal;
}

/// <summary>
///    AVA <c>avaSetBottonsAfterInit</c> method.
/// </summary>
/// <returns>
///    <c>boolean</c> as return value
/// </returns>
public boolean avaSetBottonsAfterInit()
{
    boolean         retVal;

    FormDataSource  locSalesTableDS;
    SalesTable      locSalesTable;

    retVal = true;

    locSalesTableDS = this.SalesTable_DS;
    locSalesTable   = locSalesTableDS.cursor();

    if(locSalesTable.SalesType == SalesType::Journal)
    {
        this.design().controlName(formControlStr(SalesTable, CancelOrderButton)).enabled(true);
    }

    return retVal;
}

/// <summary>
///    AVA <c>avaSetAVADlvResponsible</c> method.
/// </summary>
/// <param name="_update">
///    <c>boolean</c> as type
/// </param>
/// <returns>
///     <c>HcmWorkerRecId</c> as return value
/// </returns>
public HcmWorkerRecId avaSetAVADlvResponsible(boolean _update = false)
{
    FormDataSource  locFormDataSource;
    SalesTable      locSalesTable;
    SalesTable      locSalesTableOrig;

    Dialog          dialog;
    DialogGroup     dialogGroup;
    DialogField     dialogHCMWorkerRecId;
    HcmWorkerRecId  locHCMWorkerRecId;
    HcmWorkerRecId  locHCMWorkerRecIdDialog;

    locFormDataSource   = SalesTable_ds;
    locSalesTable       = locFormDataSource.cursor();
    locSalesTableOrig   = locSalesTable.orig();

    if(     locSalesTable.orig().SalesType  == SalesType::Journal
        &&  locSalesTable.SalesType         == SalesType::Sales
        &&  locSalesTable.AVADlvResponsible == 0                    )
    {
        locHCMWorkerRecId = HcmWorker::userId2Worker(curUserId());

        dialog = new Dialog(strfmt("@SYS82282", "@NDX:NXADlvResponsible"));

        dialogGroup             = dialog.addGroup();
        dialogGroup.caption("@NDX:NXASetResponsibility");
        dialogHCMWorkerRecId    = dialog.addFieldValue(extendedTypeStr(HcmWorkerRecId), locHCMWorkerRecId);

        dialog.run();

        if(dialog.closedOk())
        {
            // get values from the dialog fields
            locHCMWorkerRecIdDialog = dialogHCMWorkerRecId.value();
        }
        else
        {
            // set value for cancel
            locHCMWorkerRecIdDialog = 0;
        }

        locHCMWorkerRecId = locHCMWorkerRecIdDialog;

        locSalesTable.AVADlvResponsible = locHCMWorkerRecId;

        if(locSalesTable.AVADlvResponsible == 0)
        {
            locSalesTable.SalesType = SalesType::Journal;
        }

        if(_update)
        {
            ttsbegin;
            locSalesTable.selectForUpdate(true);
            locSalesTable.update();
            ttscommit;
        }
    }
    locFormDataSource.refresh();

    return locSalesTable.AVADlvResponsible;
}
